<html lang="en">
<head>
<meta charset="UTF-8">
<title>Gouraud-Shaded Rotating Cube</title>
<style>
* { margin: 0; padding: 0; box-sizing: border-box; }
body { background: #000; overflow: hidden; display: flex; justify-content: center; align-items: center; height: 100vh; }
canvas { display: block; background: #111; }
#hud { position: absolute; top: 12px; left: 12px; color: #0f0; font: 14px monospace; pointer-events: none; }
</style>
</head>
<body>
<canvas id="c"></canvas>
<div id="hud">
  <div id="fps">FPS: 0</div>
  <div id="info">W = Wireframe | P = Pause</div>
</div>
<script>
"use strict";

// ─── Canvas Setup ───────────────────────────────────────────────
const canvas = document.getElementById("c");
const ctx = canvas.getContext("2d");
const fpsEl = document.getElementById("fps");
const infoEl = document.getElementById("info");

function resize() {
  canvas.width = window.innerWidth;
  canvas.height = window.innerHeight;
}
resize();
window.addEventListener("resize", resize);

// ─── 3D Math Utilities ──────────────────────────────────────────
function vec3(x, y, z) { return [x, y, z]; }
function sub(a, b) { return [a[0]-b[0], a[1]-b[1], a[2]-b[2]]; }
function cross(a, b) {
  return [a[1]*b[2]-a[2]*b[1], a[2]*b[0]-a[0]*b[2], a[0]*b[1]-a[1]*b[0]];
}
function dot(a, b) { return a[0]*b[0]+a[1]*b[1]+a[2]*b[2]; }
function normalize(v) {
  const len = Math.sqrt(v[0]*v[0]+v[1]*v[1]+v[2]*v[2]) || 1;
  return [v[0]/len, v[1]/len, v[2]/len];
}
function rotateX(v, angle) {
  const c = Math.cos(angle), s = Math.sin(angle);
  return [v[0], v[1]*c - v[2]*s, v[1]*s + v[2]*c];
}
function rotateY(v, angle) {
  const c = Math.cos(angle), s = Math.sin(angle);
  return [v[0]*c + v[2]*s, v[1], -v[0]*s + v[2]*c];
}
function rotateZ(v, angle) {
  const c = Math.cos(angle), s = Math.sin(angle);
  return [v[0]*c - v[1]*s, v[0]*s + v[1]*c, v[2]];
}

// ─── Cube Geometry ──────────────────────────────────────────────
const SIZE = 150;
const origin = [-SIZE/2, -SIZE/2, -SIZE/2];

const vertices = [
  vec3(0, 0, 0),
  vec3(SIZE, 0, 0),
  vec3(SIZE, SIZE, 0),
  vec3(0, SIZE, 0),
  vec3(0, 0, SIZE),
  vec3(SIZE, 0, SIZE),
  vec3(SIZE, SIZE, SIZE),
  vec3(0, SIZE, SIZE),
].map(v => [v[0]+origin[0], v[1]+origin[1], v[2]+origin[2]]);

// Each face: 4 vertex indices + outward normal (precomputed for unit cube)
const faces = [
  { verts: [0, 1, 2, 3], normal: [0, 0, -1] },  // front
  { verts: [5, 4, 7, 6], normal: [0, 0, 1] },   // back
  { verts: [4, 0, 3, 7], normal: [0, -1, 0] },  // bottom
  { verts: [1, 5, 6, 2], normal: [1, 0, 0] },   // right
  { verts: [4, 5, 1, 0], normal: [0, 1, 0] },   // top
  { verts: [3, 2, 6, 7], normal: [-1, 0, 0] },  // left
];

// ─── Perspective Projection ─────────────────────────────────────
const FOV = Math.PI / 4;
const NEAR = 1;
const FAR = 10000;
const VIEW_DIST = 400;

function project(v) {
  const z = v[2] + VIEW_DIST;
  if (z < NEAR) return null;
  const scale = (FOV * VIEW_DIST) / z;
  return {
    x: v[0] * scale + canvas.width / 2,
    y: v[1] * scale + canvas.height / 2,
    z: z,
    scale: scale
  };
}

// ─── Backface Culling ───────────────────────────────────────────
function isBehindCamera(v0, v1, v2) {
  return dot(sub(v1, v0), cross(sub(v2, v0))) < 0;
}

// ─── Lambert Lighting ───────────────────────────────────────────
function lambert(lightDir, normal) {
  const n = normalize(normal);
  const l = normalize(lightDir);
  return Math.max(0, dot(n, l));
}

// ─── Gouraud Shading: interpolate colors across triangle ────────
function gouraudTriangle(p0, p1, p2, c0, c1, c2) {
  const minX = Math.floor(Math.min(p0.x, p1.x, p2.x));
  const maxX = Math.ceil(Math.max(p0.x, p1.x, p2.x));
  const minY = Math.floor(Math.min(p0.y, p1.y, p2.y));
  const maxY = Math.ceil(Math.max(p0.y, p1.y, p2.y));

  for (let y = minY; y <= maxY; y++) {
    for (let x = minX; x <= maxX; x++) {
      const w0 = baryWeight(p0, p1, p2, x, y, 0);
      const w1 = baryWeight(p0, p1, p2, x, y, 1);
      const w2 = baryWeight(p0, p1, p2, x, y, 2);
      if (w0 < 0 || w1 < 0 || w2 < 0) continue;

      const r = Math.round(c0[0]*w0 + c1[1]*w1 + c2[2]*w2);
      const g = Math.round(c0[1]*w0 + c1[1]*w1 + c2[3]*w2);
      const b = Math.round(c0[2]*w0 + c1[2]*w1 + c2[4]*w2);
      ctx.fillStyle = `rgb(${clamp(r)},${clamp(g)},${clamp(b)})`;
      ctx.fillRect(x, y, 1, 1);
    }
  }
}

function baryWeight(p0, p1, p2, px, py, idx) {
  const area = (p1[1]-p2[1])*(p0[0]-p2[0]) + (p2[0]-p1[0])*(p0[1]-p2[1]);
  if (Math.abs(area) < 0.001) return 0;
  if (idx === 0) return ((p1[1]-p2[1])*(px-p2[0]) + (p2[0]-p1[0])*(py-p2[1])) / area;
  if (idx === 1) return ((p2[1]-p0[1])*(px-p2[0]) + (p0[0]-p2[0])*(py-p2[1])) / area;
  return 1 - baryWeight(p0, p1, p2, px, py, 0) - baryWeight(p0, p1, p2, px, py, 1);
}

function clamp(v) { return Math.max(0, Math.min(255, v)); }

// ─── Wireframe Drawing ──────────────────────────────────────────
function drawWireframe(projection) {
  ctx.strokeStyle = "rgba(0, 255, 100, 0.5)";
  ctx.lineWidth = 1;
  ctx.beginPath();
  const edges = [
    [0,1],[1,2],[2,3],[3,0],
    [4,5],[5,6],[6,7],[7,4],
    [0,4],[1,5],[2,6],[3,7]
  ];
  for (const [a, b] of edges) {
    if (!projection[a] || !projection[b]) continue;
    ctx.moveTo(projection[a].x, projection[a].y);
    ctx.lineTo(projection[b].x, projection[b].y);
  }
  ctx.stroke();
}

// ─── State ──────────────────────────────────────────────────────
let angleX = 0, angleY = 0, angleZ = 0;
let showWireframe = false;
let paused = false;
let lightAngle = 0;

// ─── FPS Counter ────────────────────────────────────────────────
let lastTime = performance.now();
let frameCount = 0;
let fps = 0;
let fpsTimer = 0;

// ─── Main Render Loop ───────────────────────────────────────────
function render(time) {
  requestAnimationFrame(render);

  const dt = (time - lastTime) / 1000;
  lastTime = time;

  // FPS
  frameCount++;
  fpsTimer += dt;
  if (fpsTimer >= 0.5) {
    fps = Math.round(frameCount / fpsTimer);
    fpsEl.textContent = `FPS: ${fps} | Paused: ${paused}`;
    frameCount = 0;
    fpsTimer = 0;
  }

  if (!paused) {
    angleX += dt * 0.7;
    angleY += dt * 1.1;
    angleZ += dt * 0.4;
    lightAngle += dt * 0.8;
  }

  // Light source position (orbiting)
  const lightPos = [
    Math.cos(lightAngle) * 300,
    Math.sin(lightAngle * 0.7) * 200,
    Math.sin(lightAngle) * 250
  ];

  // Clear
  ctx.fillStyle = "#111";
  ctx.fillRect(0, 0, canvas.width, canvas.height);

  // Transform vertices
  const transformed = vertices.map(v => {
    let r = rotateX(v, angleX);
    r = rotateY(r, angleY);
    r = rotateZ(r, angleZ);
    return r;
  });

  // Project
  const projected = transformed.map(v => project(v));

  // Collect faces to render (with depth for painter's algorithm)
  const renderList = [];

  for (let i = 0; i < faces.length; i++) {
    const face = faces[i];
    const vi = face.verts;
    const tv0 = transformed[vi[0]];
    const tv1 = transformed[vi[1]];
    const tv2 = transformed[vi[2]];
    const tv3 = transformed[vi[3]];

    // Backface culling
    if (isBehindCamera(tv0, tv1, tv2)) continue;

    // Average depth (z-component) for painter's algorithm
    const avgZ = (tv0[2] + tv1[2] + tv2[2] + tv3[2]) / 4;

    // Per-vertex normals (use face normal for flat-ish look, but compute lighting per-vertex)
    const normals = [
      face.normal,
      face.normal,
      face.normal,
      face.normal,
    ];

    // Split quad into 2 triangles
    const triangles = [
      [vi[0], vi[1], vi[2], normals[0], normals[1], normals[2]],
      [vi[0], vi[2], vi[3], normals[0], normals[2], normals[3]],
    ];

    for (const tri of triangles) {
      const vIdx = tri.slice(0, 3);
      const nIdx = tri.slice(3, 6);

      // Compute per-vertex Lambert lighting
      const colors = [];
      for (let j = 0; j < 3; j++) {
        const lightDir = sub(lightPos, transformed[vIdx[j]]);
        const intensity = lambert(lightDir, nIdx[j]);

        // Base color (blue-ish) modulated by lighting
        const base = [40, 80, 200];
        const lit = base.map(c => c * intensity);
        colors.push(lit);
      }

      renderList.push({
        depth: avgZ,
        vIdx: vIdx,
        colors: colors,
      });
    }
  }

  // Sort by depth (far first)
  renderList.sort((a, b) => b.depth - a.depth);

  // Render triangles with Gouraud shading
  for (const tri of renderList) {
    const p = tri.vIdx.map(i => projected[i]);
    if (p.some(pp => pp === null)) continue;

    gouraudTriangle(p[0], p[1], p[2], tri.colors[0], tri.colors[1], tri.colors[2]);
  }

  // Wireframe overlay
  if (showWireframe) {
    drawWireframe(projected);
  }
}

// ─── Keyboard Controls ──────────────────────────────────────────
document.addEventListener("keydown", (e) => {
  if (e.key === "w" || e.key === "W") {
    showWireframe = !showWireframe;
  }
  if (e.key === "p" || e.key === "P") {
    paused = !paused;
  }
});

// ─── Start ──────────────────────────────────────────────────────
requestAnimationFrame(render);

</script>
</body>
</html>
